// Ported from the Node app's Sequelize model Branch (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BranchConfiguration : IEntityTypeConfiguration<Branch>
{
    public void Configure(EntityTypeBuilder<Branch> builder)
    {
        builder.ToTable("branches");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Code).HasColumnName("code").HasColumnType("nvarchar(12)").HasMaxLength(12);
        builder.Property(e => e.Address).HasColumnName("address").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.Phone).HasColumnName("phone").HasColumnType("nvarchar(30)").HasMaxLength(30);
        builder.Property(e => e.Incharge).HasColumnName("incharge").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.IsMain).HasColumnName("is_main");
        builder.HasIndex(e => e.Name).IsUnique();
        builder.HasIndex(e => e.Code).IsUnique();
    }
}
